def comps(grid, color=None):
    h,w=len(grid),len(grid[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if seen[i][j] or (color is not None and grid[i][j]!=color): continue
            c=grid[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx]==c:
                        seen[ny][nx]=True; q.append((ny,nx))
            out.append(cells)
    return out

def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    H,W=h,w
    def inb(y,x): return 0<=y<H and 0<=x<W
    for cells in comps(grid):
        touches=any(y in(0,H-1) or x in(0,W-1) for y,x in cells)
        if touches: continue
        cs=set(grid[y][x] for y,x in cells)
        if len(cs)!=1: continue
        # neighbors
        nbr=set()
        s=set(cells)
        for y,x in cells:
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if inb(ny,nx) and (ny,nx) not in s: nbr.add(grid[ny][nx])
        if len(nbr)!=1: continue
        # does this component enclose anything? flood from border avoiding these cells
        blocked=s
        seen=[[False]*W for _ in range(H)]; q=deque()
        for j in range(W):
            for i in (0,H-1):
                if (i,j) not in blocked and not seen[i][j]: seen[i][j]=True; q.append((i,j))
        for i in range(H):
            for j in (0,W-1):
                if (i,j) not in blocked and not seen[i][j]: seen[i][j]=True; q.append((i,j))
        while q:
            y,x=q.popleft()
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and (ny,nx) not in blocked:
                    seen[ny][nx]=True; q.append((ny,nx))
        enclosed=sum(1 for i in range(H) for j in range(W) if not seen[i][j])
        if enclosed: continue  # it's a frame, not an interior
        fill = 2 if len(cells)%4==0 else 7
        for y,x in cells: out[y][x]=fill
    return out

